//			SetCreatedAt(v+v).
//		}).
//		Exec(ctx)
func (_c *ItemCreateBulk) OnConflict(opts ...sql.ConflictOption) *ItemUpsertBulk {
	_c.conflict = opts
	return &ItemUpsertBulk{
		create: _c,
	}
}

// OnConflictColumns calls `OnConflict` and configures the columns
